-- Apply once to databases created before commit 8132d0f.
BEGIN;

CREATE TABLE "policy_rag_requests" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "run_id" bigint NOT NULL REFERENCES "orchestrator_runs" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  "checkout_site" varchar(500) NOT NULL,
  "case_type" varchar(50),
  "consumer_request" text NOT NULL,
  "purchase_date" date,
  "item_amount" jsonb,
  "confirmed_facts" text[] NOT NULL,
  "unresolved_facts" text[] NOT NULL DEFAULT '{}'::text[],
  "created_at" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "policy_rag_requests_case_type_check"
    CHECK (case_type IS NULL OR case_type IN ('REFUND_DELAY', 'REFUND_NOT_PROCESSED', 'DUPLICATE_CHARGE', 'PAYMENT_CORRECTION'))
);

CREATE INDEX ON "policy_rag_requests" ("run_id");

CREATE TABLE "policy_rag_results" (
  "request_id" bigint PRIMARY KEY REFERENCES "policy_rag_requests" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  "status" varchar(30) NOT NULL,
  "clauses" jsonb NOT NULL DEFAULT '[]'::jsonb,
  "note" text,
  CONSTRAINT "policy_rag_results_status_check"
    CHECK (status IN ('COMPLETED', 'NOT_FOUND', 'INSUFFICIENT_FACTS', 'FAILED')),
  CONSTRAINT "policy_rag_results_clauses_array_check"
    CHECK (jsonb_typeof(clauses) = 'array')
);

CREATE TABLE "policy_vector_store" (
  "id" uuid PRIMARY KEY,
  "content" text NOT NULL,
  "metadata" jsonb NOT NULL,
  "embedding" vector NOT NULL
);

COMMENT ON COLUMN "policy_rag_results"."clauses" IS '검토한 공식 조항의 JSON 배열. 각 객체는 quoteEn, section, source, applicability를 담는다.';
COMMENT ON COLUMN "policy_vector_store"."metadata" IS '필수 키는 platform, site, sourceUrl, policyTitle, updatedAt이다. updatedAt은 마지막 정상 적재 시각이다.';

COMMIT;
